BEGIN
  FOR item IN SELECT value FROM jsonb_array_elements($placement$[{"tag": "placement-v2-cloud-1-beginner", "domain": "CLOUD", "level": "beginner", "prompt": "In this passage, what does \"provision\" mean?", "context": "Teams provision virtual machines when demand rises and release them after the event. They pay for the resources while they are running.", "options": ["create and prepare resources for use", "remove all stored files", "publish an advertisement", "inspect a cable"], "correctIndex": 0, "explanation": "Trong ngữ cảnh này, \"provision\" mang nghĩa: create and prepare resources for use."}, {"tag": "placement-v2-cloud-1-intermediate", "domain": "CLOUD", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Teams provision virtual machines when demand rises and release them after the event. They pay for the resources while they are running.", "options": ["Virtual machines must always run for a full year.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "Resources can be added temporarily for a busy event."], "correctIndex": 3, "explanation": "Ý được đoạn văn hỗ trợ: Resources can be added temporarily for a busy event."}, {"tag": "placement-v2-cloud-1-advanced", "domain": "CLOUD", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Teams provision virtual machines when demand rises and release them after the event. They pay for the resources while they are running.", "options": ["The passage discusses provision.", "The passage describes a technical workflow or limitation.", "Virtual machines must always run for a full year.", "Resources can be added temporarily for a busy event."], "correctIndex": 2, "explanation": "Không thể suy ra nhận định: Virtual machines must always run for a full year. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cloud-2-beginner", "domain": "CLOUD", "level": "beginner", "prompt": "In this passage, what does \"redundant\" mean?", "context": "The service uses redundant servers in separate locations. If one server fails, another can continue serving requests, although failover may take a few seconds.", "options": ["too expensive to maintain", "shared with every visitor", "encrypted with a password", "available as an additional copy or backup"], "correctIndex": 3, "explanation": "Trong ngữ cảnh này, \"redundant\" mang nghĩa: available as an additional copy or backup."}, {"tag": "placement-v2-cloud-2-intermediate", "domain": "CLOUD", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "The service uses redundant servers in separate locations. If one server fails, another can continue serving requests, although failover may take a few seconds.", "options": ["The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "An additional server helps the service continue during a failure.", "The design guarantees that no request will ever fail."], "correctIndex": 2, "explanation": "Ý được đoạn văn hỗ trợ: An additional server helps the service continue during a failure."}, {"tag": "placement-v2-cloud-2-advanced", "domain": "CLOUD", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "The service uses redundant servers in separate locations. If one server fails, another can continue serving requests, although failover may take a few seconds.", "options": ["The passage describes a technical workflow or limitation.", "The design guarantees that no request will ever fail.", "An additional server helps the service continue during a failure.", "The passage discusses redundant."], "correctIndex": 1, "explanation": "Không thể suy ra nhận định: The design guarantees that no request will ever fail. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cloud-3-beginner", "domain": "CLOUD", "level": "beginner", "prompt": "In this passage, what does \"on demand\" mean?", "context": "Storage is allocated on demand. Customers request more space when needed rather than purchasing the maximum amount in advance.", "options": ["without checking permissions", "after the contract ends", "when it is needed", "only once every year"], "correctIndex": 2, "explanation": "Trong ngữ cảnh này, \"on demand\" mang nghĩa: when it is needed."}, {"tag": "placement-v2-cloud-3-intermediate", "domain": "CLOUD", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Storage is allocated on demand. Customers request more space when needed rather than purchasing the maximum amount in advance.", "options": ["The passage requires every system to be publicly accessible.", "Customers can request extra space as their needs grow.", "All allocated storage is always free of charge.", "The passage says no checks are necessary."], "correctIndex": 1, "explanation": "Ý được đoạn văn hỗ trợ: Customers can request extra space as their needs grow."}, {"tag": "placement-v2-cloud-3-advanced", "domain": "CLOUD", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Storage is allocated on demand. Customers request more space when needed rather than purchasing the maximum amount in advance.", "options": ["All allocated storage is always free of charge.", "Customers can request extra space as their needs grow.", "The passage discusses on demand.", "The passage describes a technical workflow or limitation."], "correctIndex": 0, "explanation": "Không thể suy ra nhận định: All allocated storage is always free of charge. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cloud-4-beginner", "domain": "CLOUD", "level": "beginner", "prompt": "In this passage, what does \"mitigate\" mean?", "context": "Encryption helps mitigate the impact of exposed storage media. Access controls are still required to prevent unauthorized users from reading live data.", "options": ["copy data to public storage", "reduce the severity of a risk", "eliminate every possible threat", "increase the number of users"], "correctIndex": 1, "explanation": "Trong ngữ cảnh này, \"mitigate\" mang nghĩa: reduce the severity of a risk."}, {"tag": "placement-v2-cloud-4-intermediate", "domain": "CLOUD", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Encryption helps mitigate the impact of exposed storage media. Access controls are still required to prevent unauthorized users from reading live data.", "options": ["Encryption and access controls address different risks.", "Encryption makes access controls unnecessary.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible."], "correctIndex": 0, "explanation": "Ý được đoạn văn hỗ trợ: Encryption and access controls address different risks."}, {"tag": "placement-v2-cloud-4-advanced", "domain": "CLOUD", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Encryption helps mitigate the impact of exposed storage media. Access controls are still required to prevent unauthorized users from reading live data.", "options": ["Encryption and access controls address different risks.", "The passage discusses mitigate.", "The passage describes a technical workflow or limitation.", "Encryption makes access controls unnecessary."], "correctIndex": 3, "explanation": "Không thể suy ra nhận định: Encryption makes access controls unnecessary. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cloud-5-beginner", "domain": "CLOUD", "level": "beginner", "prompt": "In this passage, what does \"whereas\" mean?", "context": "The customer manages application data, whereas the provider maintains the physical data center. Both parties have security responsibilities.", "options": ["while indicating a contrast", "because of a previous failure", "unless a condition is met", "in addition to a deadline"], "correctIndex": 0, "explanation": "Trong ngữ cảnh này, \"whereas\" mang nghĩa: while indicating a contrast."}, {"tag": "placement-v2-cloud-5-intermediate", "domain": "CLOUD", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "The customer manages application data, whereas the provider maintains the physical data center. Both parties have security responsibilities.", "options": ["The provider alone is responsible for all customer data decisions.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "Customer and provider responsibilities cover different parts of the system."], "correctIndex": 3, "explanation": "Ý được đoạn văn hỗ trợ: Customer and provider responsibilities cover different parts of the system."}, {"tag": "placement-v2-cloud-5-advanced", "domain": "CLOUD", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "The customer manages application data, whereas the provider maintains the physical data center. Both parties have security responsibilities.", "options": ["The passage discusses whereas.", "The passage describes a technical workflow or limitation.", "The provider alone is responsible for all customer data decisions.", "Customer and provider responsibilities cover different parts of the system."], "correctIndex": 2, "explanation": "Không thể suy ra nhận định: The provider alone is responsible for all customer data decisions. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cybersec-1-beginner", "domain": "CYBERSEC", "level": "beginner", "prompt": "In this passage, what does \"revoke\" mean?", "context": "Administrators revoke access when an employee leaves. Removing the account permissions prevents future authorized use of company systems.", "options": ["take away a permission", "approve a new request", "compress a file", "record a training session"], "correctIndex": 0, "explanation": "Trong ngữ cảnh này, \"revoke\" mang nghĩa: take away a permission."}, {"tag": "placement-v2-cybersec-1-intermediate", "domain": "CYBERSEC", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Administrators revoke access when an employee leaves. Removing the account permissions prevents future authorized use of company systems.", "options": ["Removing permissions erases every copy of data the employee already downloaded.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "An employee who leaves should lose access permissions."], "correctIndex": 3, "explanation": "Ý được đoạn văn hỗ trợ: An employee who leaves should lose access permissions."}, {"tag": "placement-v2-cybersec-1-advanced", "domain": "CYBERSEC", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Administrators revoke access when an employee leaves. Removing the account permissions prevents future authorized use of company systems.", "options": ["The passage discusses revoke.", "The passage describes a technical workflow or limitation.", "Removing permissions erases every copy of data the employee already downloaded.", "An employee who leaves should lose access permissions."], "correctIndex": 2, "explanation": "Không thể suy ra nhận định: Removing permissions erases every copy of data the employee already downloaded. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cybersec-2-beginner", "domain": "CYBERSEC", "level": "beginner", "prompt": "In this passage, what does \"authenticate\" mean?", "context": "The system authenticates users with a password and a second factor before allowing them to sign in. Permission checks then determine which records they may view.", "options": ["approve every requested action", "delete inactive accounts", "hide the login page", "verify an identity"], "correctIndex": 3, "explanation": "Trong ngữ cảnh này, \"authenticate\" mang nghĩa: verify an identity."}, {"tag": "placement-v2-cybersec-2-intermediate", "domain": "CYBERSEC", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "The system authenticates users with a password and a second factor before allowing them to sign in. Permission checks then determine which records they may view.", "options": ["The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "Identity verification happens before record-level permission checks.", "Every authenticated user can view all records."], "correctIndex": 2, "explanation": "Ý được đoạn văn hỗ trợ: Identity verification happens before record-level permission checks."}, {"tag": "placement-v2-cybersec-2-advanced", "domain": "CYBERSEC", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "The system authenticates users with a password and a second factor before allowing them to sign in. Permission checks then determine which records they may view.", "options": ["The passage describes a technical workflow or limitation.", "Every authenticated user can view all records.", "Identity verification happens before record-level permission checks.", "The passage discusses authenticate."], "correctIndex": 1, "explanation": "Không thể suy ra nhận định: Every authenticated user can view all records. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cybersec-3-beginner", "domain": "CYBERSEC", "level": "beginner", "prompt": "In this passage, what does \"quarantine\" mean?", "context": "A suspicious file is quarantined in an isolated area while analysts examine it. The file is not allowed to execute on the workstation.", "options": ["permanently accept a connection", "grant full administrator rights", "isolate something for investigation", "publish something for general use"], "correctIndex": 2, "explanation": "Trong ngữ cảnh này, \"quarantine\" mang nghĩa: isolate something for investigation."}, {"tag": "placement-v2-cybersec-3-intermediate", "domain": "CYBERSEC", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "A suspicious file is quarantined in an isolated area while analysts examine it. The file is not allowed to execute on the workstation.", "options": ["The passage requires every system to be publicly accessible.", "The suspicious file is kept from running during analysis.", "Every quarantined file has already been proven malicious.", "The passage says no checks are necessary."], "correctIndex": 1, "explanation": "Ý được đoạn văn hỗ trợ: The suspicious file is kept from running during analysis."}, {"tag": "placement-v2-cybersec-3-advanced", "domain": "CYBERSEC", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "A suspicious file is quarantined in an isolated area while analysts examine it. The file is not allowed to execute on the workstation.", "options": ["Every quarantined file has already been proven malicious.", "The suspicious file is kept from running during analysis.", "The passage discusses quarantine.", "The passage describes a technical workflow or limitation."], "correctIndex": 0, "explanation": "Không thể suy ra nhận định: Every quarantined file has already been proven malicious. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cybersec-4-beginner", "domain": "CYBERSEC", "level": "beginner", "prompt": "In this passage, what does \"least privilege\" mean?", "context": "Under least privilege, a support agent may read customer tickets but cannot change billing settings. Additional permissions require approval.", "options": ["unlimited access after signing in", "only the permissions needed for a task", "the highest possible access level", "the same password for every user"], "correctIndex": 1, "explanation": "Trong ngữ cảnh này, \"least privilege\" mang nghĩa: only the permissions needed for a task."}, {"tag": "placement-v2-cybersec-4-intermediate", "domain": "CYBERSEC", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Under least privilege, a support agent may read customer tickets but cannot change billing settings. Additional permissions require approval.", "options": ["Ticket access does not automatically allow billing changes.", "Least privilege prevents every kind of security incident.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible."], "correctIndex": 0, "explanation": "Ý được đoạn văn hỗ trợ: Ticket access does not automatically allow billing changes."}, {"tag": "placement-v2-cybersec-4-advanced", "domain": "CYBERSEC", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Under least privilege, a support agent may read customer tickets but cannot change billing settings. Additional permissions require approval.", "options": ["Ticket access does not automatically allow billing changes.", "The passage discusses least privilege.", "The passage describes a technical workflow or limitation.", "Least privilege prevents every kind of security incident."], "correctIndex": 3, "explanation": "Không thể suy ra nhận định: Least privilege prevents every kind of security incident. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-cybersec-5-beginner", "domain": "CYBERSEC", "level": "beginner", "prompt": "In this passage, what does \"despite\" mean?", "context": "Despite using strong encryption, the team suffered a breach because an attacker stole an administrator session. The team strengthened session controls afterward.", "options": ["even though", "only if", "as a direct result of", "before"], "correctIndex": 0, "explanation": "Trong ngữ cảnh này, \"despite\" mang nghĩa: even though."}, {"tag": "placement-v2-cybersec-5-intermediate", "domain": "CYBERSEC", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Despite using strong encryption, the team suffered a breach because an attacker stole an administrator session. The team strengthened session controls afterward.", "options": ["The incident proves encryption has no security value.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "Encryption alone did not prevent misuse of a stolen session."], "correctIndex": 3, "explanation": "Ý được đoạn văn hỗ trợ: Encryption alone did not prevent misuse of a stolen session."}, {"tag": "placement-v2-cybersec-5-advanced", "domain": "CYBERSEC", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Despite using strong encryption, the team suffered a breach because an attacker stole an administrator session. The team strengthened session controls afterward.", "options": ["The passage discusses despite.", "The passage describes a technical workflow or limitation.", "The incident proves encryption has no security value.", "Encryption alone did not prevent misuse of a stolen session."], "correctIndex": 2, "explanation": "Không thể suy ra nhận định: The incident proves encryption has no security value. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-networking-1-beginner", "domain": "NETWORKING", "level": "beginner", "prompt": "In this passage, what does \"route\" mean?", "context": "The router selects a route for each packet based on its destination. The selected path may change if a link becomes unavailable.", "options": ["a path used to reach a destination", "a secret used to sign in", "a copy of a local document", "a command to close a browser"], "correctIndex": 0, "explanation": "Trong ngữ cảnh này, \"route\" mang nghĩa: a path used to reach a destination."}, {"tag": "placement-v2-networking-1-intermediate", "domain": "NETWORKING", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "The router selects a route for each packet based on its destination. The selected path may change if a link becomes unavailable.", "options": ["Every packet always follows the same physical path.", "The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "A failed link can cause packets to use another path."], "correctIndex": 3, "explanation": "Ý được đoạn văn hỗ trợ: A failed link can cause packets to use another path."}, {"tag": "placement-v2-networking-1-advanced", "domain": "NETWORKING", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "The router selects a route for each packet based on its destination. The selected path may change if a link becomes unavailable.", "options": ["The passage discusses route.", "The passage describes a technical workflow or limitation.", "Every packet always follows the same physical path.", "A failed link can cause packets to use another path."], "correctIndex": 2, "explanation": "Không thể suy ra nhận định: Every packet always follows the same physical path. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-networking-2-beginner", "domain": "NETWORKING", "level": "beginner", "prompt": "In this passage, what does \"resolve\" mean?", "context": "A DNS resolver translates a host name into an IP address. Cached results may be reused until their time to live expires.", "options": ["erase every cached response", "encrypt all network traffic", "assign a user role", "find the address associated with a name"], "correctIndex": 3, "explanation": "Trong ngữ cảnh này, \"resolve\" mang nghĩa: find the address associated with a name."}, {"tag": "placement-v2-networking-2-intermediate", "domain": "NETWORKING", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "A DNS resolver translates a host name into an IP address. Cached results may be reused until their time to live expires.", "options": ["The passage says no checks are necessary.", "The passage requires every system to be publicly accessible.", "A cached address can be used while it remains valid.", "DNS resolution proves a website is safe to visit."], "correctIndex": 2, "explanation": "Ý được đoạn văn hỗ trợ: A cached address can be used while it remains valid."}, {"tag": "placement-v2-networking-2-advanced", "domain": "NETWORKING", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "A DNS resolver translates a host name into an IP address. Cached results may be reused until their time to live expires.", "options": ["The passage describes a technical workflow or limitation.", "DNS resolution proves a website is safe to visit.", "A cached address can be used while it remains valid.", "The passage discusses resolve."], "correctIndex": 1, "explanation": "Không thể suy ra nhận định: DNS resolution proves a website is safe to visit. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-networking-3-beginner", "domain": "NETWORKING", "level": "beginner", "prompt": "In this passage, what does \"latency\" mean?", "context": "Latency measures how long a request takes to travel to a service and return. A high-bandwidth connection may still have noticeable latency.", "options": ["number of logged-in administrators", "length of a password", "delay in communication", "amount of disk storage"], "correctIndex": 2, "explanation": "Trong ngữ cảnh này, \"latency\" mang nghĩa: delay in communication."}, {"tag": "placement-v2-networking-3-intermediate", "domain": "NETWORKING", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "Latency measures how long a request takes to travel to a service and return. A high-bandwidth connection may still have noticeable latency.", "options": ["The passage requires every system to be publicly accessible.", "More bandwidth does not necessarily remove communication delay.", "High bandwidth always guarantees an immediate response.", "The passage says no checks are necessary."], "correctIndex": 1, "explanation": "Ý được đoạn văn hỗ trợ: More bandwidth does not necessarily remove communication delay."}, {"tag": "placement-v2-networking-3-advanced", "domain": "NETWORKING", "level": "advanced", "prompt": "Which claim goes beyond what the passage supports?", "context": "Latency measures how long a request takes to travel to a service and return. A high-bandwidth connection may still have noticeable latency.", "options": ["High bandwidth always guarantees an immediate response.", "More bandwidth does not necessarily remove communication delay.", "The passage discusses latency.", "The passage describes a technical workflow or limitation."], "correctIndex": 0, "explanation": "Không thể suy ra nhận định: High bandwidth always guarantees an immediate response. Đối chiếu điều kiện và giới hạn được nêu trong đoạn văn."}, {"tag": "placement-v2-networking-4-beginner", "domain": "NETWORKING", "level": "beginner", "prompt": "In this passage, what does \"drop\" mean?", "context": "The firewall drops packets that do not match an allowed rule. Those packets are discarded rather than forwarded to the internal service.", "options": ["copy to every server", "discard without forwarding", "save as an approved backup", "grant access automatically"], "correctIndex": 1, "explanation": "Trong ngữ cảnh này, \"drop\" mang nghĩa: discard without forwarding."}, {"tag": "placement-v2-networking-4-intermediate", "domain": "NETWORKING", "level": "intermediate", "prompt": "Which statement best paraphrases the passage?", "context": "The firewall drops packets that do not match an allowed rule. Those packets are di