tance", "a promise that incidents can never occur", "a method for storing all source code", "a replacement for every application test"], "correctIndex": 0, "explanation": "Đáp án được hỗ trợ bởi đoạn văn: a service arrangement describing available assistance"}, {"tag": "placement-v2-aws-clf-c02-d4-5-intermediate", "domain": "AWS_CLF_C02_D4", "level": "intermediate", "prompt": "Which statement best summarizes the passage?", "context": "The team compares support plans according to the help its workload needs. It checks the available channels and response-time targets before choosing. A support plan does not replace the team's own incident procedures.", "options": ["The passage says that no further customer decisions are needed.", "The team selects support based on its assistance needs and plan terms.", "The passage recommends ignoring changes in workload usage.", "The passage guarantees that every operational problem disappears."], "correctIndex": 1, "explanation": "Đáp án được hỗ trợ bởi đoạn văn: The team selects support based on its assistance needs and plan terms."}, {"tag": "placement-v2-aws-clf-c02-d4-5-advanced", "domain": "AWS_CLF_C02_D4", "level": "advanced", "prompt": "Which conclusion is supported by the passage?", "context": "The team compares support plans according to the help its workload needs. It checks the available channels and response-time targets before choosing. A support plan does not replace the team's own incident procedures.", "options": ["The passage says that no further customer decisions are needed.", "The passage recommends ignoring changes in workload usage.", "The team still needs incident procedures after selecting a support plan.", "The passage guarantees that every operational problem disappears."], "correctIndex": 2, "explanation": "Đáp án được hỗ trợ bởi đoạn văn: The team still needs incident procedures after selecting a support plan."}]$placement$::jsonb)
  LOOP
    SELECT id INTO domain_id FROM domains WHERE code = item->>'domain' AND is_active;
    SELECT id INTO level_id FROM levels WHERE code = item->>'level' AND is_active;
    IF domain_id IS NULL OR level_id IS NULL OR EXISTS (
      SELECT 1 FROM questions WHERE topics @> ARRAY[item->>'tag']
    ) THEN CONTINUE; END IF;
    question_id := md5(item->>'tag')::uuid;
    INSERT INTO questions (id, type, skill, prompt, context, explanation, domain_id, level_id, topics, points, status, updated_at)
    VALUES (question_id, 'single_choice', 'reading', item->>'prompt', item->>'context', item->>'explanation', domain_id, level_id,
      ARRAY['placement', 'placement-v2', item->>'tag'], 1, 'published', CURRENT_TIMESTAMP);
    INSERT INTO question_options (id, question_id, key, text, is_correct, "order")
    SELECT md5((item->>'tag') || ':' || (choice.ordinality - 1)::text)::uuid, question_id,
      chr(64 + choice.ordinality::int), choice.value, choice.ordinality - 1 = (item->>'correctIndex')::int, choice.ordinality - 1
    FROM jsonb_array_elements_text(item->'options') WITH ORDINALITY AS choice(value, ordinality);
  END LOOP;
END;
